-- Synthetic state only, disposable PostgreSQL, rollback. Never execute on hosted Supabase.
begin;
create temporary table email_assertions(name text primary key);
grant insert on email_assertions to authenticated,anon,service_role;
create function pg_temp.email_check(ok boolean,name text) returns void language plpgsql as $$ begin
 if ok is distinct from true then raise exception 'Email assertion failed: %',name; end if;
 insert into email_assertions values(name);end $$;
select set_config('test.email_operation',(select operation_id::text from public.fiscal_documents limit 1),true);
select set_config('test.email_batch',(select batch_id::text from public.fiscal_operations where id=current_setting('test.email_operation')::uuid),true);
