 begin perform public.claim_invoice_email();raise exception 'Client claimed emails';exception when insufficient_privilege then perform pg_temp.email_check(true,'claim is server only');end;
 begin perform * from private.invoice_email_execution;raise exception 'Token leaked';exception when insufficient_privilege then perform pg_temp.email_check(true,'lease and attachment not public');end;
 begin insert into public.invoice_email_batches values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),now());raise exception 'Client opted in foreign batch';exception when insufficient_privilege then perform pg_temp.email_check(true,'batch enrollment is server only');end;
end $$;
reset role;
set role service_role;
do $$ begin
 begin perform public.enable_invoice_email('00000000-0000-4000-8000-000000000002',current_setting('test.email_batch')::uuid);raise exception 'Foreign actor enabled email';exception when insufficient_privilege then perform pg_temp.email_check(true,'enrollment checks actor ownership');end;
end $$;
select pg_temp.email_check(not public.invoice_email_ready(current_setting('test.email_tenant')::uuid),'existing documents are not automatically enrolled');
select public.enable_invoice_email(current_setting('test.email_actor')::uuid,current_setting('test.email_batch')::uuid);
select public.enable_invoice_email(current_setting('test.email_actor')::uuid,current_setting('test.email_batch')::uuid);
reset role;
select pg_temp.email_check((select count(*)=1 from public.invoice_email_deliveries),'repeated opt in creates one delivery per document');
select set_config('test.email_id',(select id::text from public.invoice_email_deliveries limit 1),true);
set role authenticated;
select pg_temp.email_check((select count(*)=1 from public.invoice_email_deliveries),'owner sees delivery metadata');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000002"}',true);
select pg_temp.email_check((select count(*)=0 from public.invoice_email_deliveries),'foreign owner sees no delivery');
reset role;
set role service_role;
select set_config('test.email_claim',public.claim_invoice_email(current_setting('test.email_tenant')::uuid)::text,true);
select pg_temp.email_check(public.claim_invoice_email(current_setting('test.email_tenant')::uuid) is null,'claimed job cannot be claimed twice');
select pg_temp.email_check(public.begin_invoice_email(current_setting('test.email_id')::uuid,gen_random_uuid(),array['brevo'],'test@example.com','nfse@example.com',true,repeat('a',64)) is null,'wrong lease cannot dispatch');
do $$ begin
 begin perform public.begin_invoice_email(current_setting('test.email_id')::uuid,(current_setting('test.email_claim')::jsonb->>'token')::uuid,array['brevo'],'vendor@example.com','nfse@example.com',false,repeat('a',64));raise exception 'Homologation sent as production';exception when invalid_parameter_value then perform pg_temp.email_check(true,'homologation cannot dispatch as production');end;
end $$;
reset role;
insert into private.invoice_email_attempts(delivery_id,provider) select current_setting('test.email_id')::uuid,'brevo' from generate_series(1,300);
set role service_role;
select pg_temp.email_check(public.begin_invoice_email(current_setting('test.email_id')::uuid,(current_setting('test.email_claim')::jsonb->>'token')::uuid,array['brevo','sendpulse','mailjet'],'test@example.com','nfse@example.com',true,repeat('a',64))->>'provider'='sendpulse','Brevo quota 300 falls through to SendPulse');
reset role;
select pg_temp.email_check((select next_allowed_at>=now()+interval '74 seconds' from private.invoice_email_providers where provider='sendpulse'),'SendPulse spacing is durably at least 75 seconds');
set role service_role;
select pg_temp.email_check(public.begin_invoice_email(current_setting('test.email_id')::uuid,(current_setting('test.email_claim')::jsonb->>'token')::uuid,array['brevo','sendpulse','mailjet'],'test@example.com','nfse@example.com',true,repeat('a',64)) is null,'one external send intent per lease');
select pg_temp.email_check(public.finish_invoice_email(current_setting('test.email_id')::uuid,(current_setting('test.email_claim')::jsonb->>'token')::uuid,'quota_rejected',null,'vendor@example.com'),'explicit quota rejection completed');
select set_config('test.email_claim',public.claim_invoice_email(current_setting('test.email_tenant')::uuid)::text,true);
select pg_temp.email_check(public.begin_invoice_email(current_setting('test.email_id')::uuid,(current_setting('test.email_claim')::jsonb->>'token')::uuid,array['brevo','sendpulse','mailjet'],'test@example.com','nfse@example.com',true,repeat('a',64))->>'provider'='mailjet','explicit 429/402 falls through to tertiary provider');
