select pg_temp.email_check(not public.retry_invoice_email(current_setting('test.email_actor')::uuid,current_setting('test.email_id')::uuid),'uncertain acceptance forbids automatic re-send');
select pg_temp.email_check(public.claim_invoice_email(current_setting('test.email_tenant')::uuid) is null,'uncertain job never returns to queue');
reset role;
select pg_temp.email_check((select status='authorized' and transmit_count=1 from public.fiscal_operations where id=current_setting('test.email_operation')::uuid),'email failure never changes fiscal authorization or dispatch count');
select pg_temp.email_check((select count(*)::text=current_setting('test.email_fiscal_count') from public.fiscal_operations),'email retries cannot create invoices');
-- Reset synthetic metadata in this disposable transaction to exercise expired leases and acceptance.
update public.invoice_email_deliveries set status='queued',next_run_at=now(),provider_cursor=0,attempts=0;
update private.invoice_email_providers set paused_until=now(),busy_until=now(),next_allowed_at=now();
delete from private.invoice_email_attempts;
set role service_role;
select set_config('test.email_claim',public.claim_invoice_email(current_setting('test.email_tenant')::uuid)::text,true);
reset role;
