select pg_temp.email_check((current_setting('test.email_claim')::jsonb->>'token')<>(current_setting('test.email_newclaim')::jsonb->>'token'),'expired preparation receives fresh fencing token');
select pg_temp.email_check(not public.finish_invoice_email(current_setting('test.email_id')::uuid,(current_setting('test.email_claim')::jsonb->>'token')::uuid,'invalid_email'),'stale worker cannot finish new lease');
select public.begin_invoice_email(current_setting('test.email_id')::uuid,(current_setting('test.email_newclaim')::jsonb->>'token')::uuid,array['brevo'],'test@example.com','nfse@example.com',true,repeat('a',64));
select pg_temp.email_check(public.finish_invoice_email(current_setting('test.email_id')::uuid,(current_setting('test.email_newclaim')::jsonb->>'token')::uuid,'accepted','synthetic-provider-id','vendor@example.com'),'accepted provider acknowledgement persisted');
select pg_temp.email_check(not public.finish_invoice_email(current_setting('test.email_id')::uuid,(current_setting('test.email_newclaim')::jsonb->>'token')::uuid,'accepted','synthetic-provider-id','vendor@example.com'),'completion commits once');
select pg_temp.email_check(not public.retry_invoice_email(current_setting('test.email_actor')::uuid,current_setting('test.email_id')::uuid),'accepted is not eligible for automatic retry');
reset role;
select pg_temp.email_check((select status='accepted' from public.invoice_email_deliveries limit 1),'accepted is not mislabeled as delivered');
update public.invoice_email_deliveries set status='blocked',reason='invalid_email',destination=null;
set role service_role;
do $$ begin
 begin perform public.retry_invoice_email('00000000-0000-4000-8000-000000000002',current_setting('test.email_id')::uuid,'correct@example.com');raise exception 'Foreign actor corrected delivery';exception when insufficient_privilege then perform pg_temp.email_check(true,'correction checks ownership');end;
 begin perform public.retry_invoice_email(current_setting('test.email_actor')::uuid,current_setting('test.email_id')::uuid,E'bad@example.com\nBcc:other@example.com');raise exception 'Header injection accepted';exception when invalid_parameter_value then perform pg_temp.email_check(true,'correction rejects header injection');end;
end $$;
select pg_temp.email_check(public.retry_invoice_email(current_setting('test.email_actor')::uuid,current_setting('test.email_id')::uuid,'correct@example.com'),'owner corrects missing email without another invoice');
reset role;
select pg_temp.email_check((select destination='correct@example.com' and status='queued' from public.invoice_email_deliveries limit 1),'corrected destination is preserved for retry');
-- Extra authorized state fixture only, within rollback; no live XML, signature or transport.
select set_config('test.email_second_op',gen_random_uuid()::text,true);
insert into public.fiscal_operations select (jsonb_populate_record(null::public.fiscal_operations,to_jsonb(o)||jsonb_build_object('id',current_setting('test.email_second_op'),'dps_id','DPS'||lpad('987654321',42,'0'),'dps_number','987654321'))).* from public.fiscal_operations o where id=current_setting('test.email_operation')::uuid;
