update public.invoice_email_deliveries set status='queued',next_run_at=now(),provider_cursor=0,attempts=0;
update private.invoice_email_providers set paused_until=now(),busy_until=now(),next_allowed_at=now();
delete from private.invoice_email_attempts;
insert into private.invoice_email_attempts(delivery_id,provider) select current_setting('test.email_id')::uuid,'brevo' from generate_series(1,299);
create function pg_temp.email_begin(claim jsonb) returns jsonb language sql as $$ select public.begin_invoice_email((claim->>'id')::uuid,(claim->>'token')::uuid,array['brevo','sendpulse','mailjet'],'test@example.com','nfse@example.com',true,repeat('a',64)); $$;
create function pg_temp.email_finish(claim jsonb) returns boolean language sql as $$ select public.finish_invoice_email((claim->>'id')::uuid,(claim->>'token')::uuid,'accepted','synthetic-ack'); $$;
select set_config('test.email_a',public.claim_invoice_email(current_setting('test.email_tenant')::uuid)::text,true);
select set_config('test.email_b',public.claim_invoice_email(current_setting('test.email_tenant')::uuid)::text,true);
