insert into private.invoice_email_attempts(delivery_id,provider) select current_setting('test.email_id')::uuid,'mailjet' from generate_series(1,199);
update public.invoice_email_deliveries set status='queued',next_run_at=now(),provider_cursor=0,attempts=0 where id=(current_setting('test.email_b')::jsonb->>'id')::uuid;
