select pg_temp.email_check((select next_run_at>now() and status='queued' from public.invoice_email_deliveries where id=(current_setting('test.email_b')::jsonb->>'id')::uuid),'exhausted providers remain durable future work');
-- A crash after intent must become uncertain, never a new provider send.
delete from private.invoice_email_attempts;
update private.invoice_email_providers set paused_until=now(),busy_until=now(),next_allowed_at=now();
update public.invoice_email_deliveries set status='queued',next_run_at=now(),provider_cursor=0,attempts=0 where id=(current_setting('test.email_a')::jsonb->>'id')::uuid;
select set_config('test.email_a',public.claim_invoice_email(current_setting('test.email_tenant')::uuid)::text,true);
select pg_temp.email_begin(current_setting('test.email_a')::jsonb);
update private.invoice_email_execution set lease_until=now()-interval '1 second' where delivery_id=(current_setting('test.email_a')::jsonb->>'id')::uuid;
select public.claim_invoice_email(current_setting('test.email_tenant')::uuid);
select pg_temp.email_check((select status='uncertain' from public.invoice_email_deliveries where id=(current_setting('test.email_a')::jsonb->>'id')::uuid),'expired dispatch lease becomes uncertain without failover');

select 'EMAIL_ASSERTIONS='||count(*) from email_assertions;
rollback;
